return ['domain'=>'zinn-offload','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'te','project-id-version'=>'zinn-offload','pot-creation-date'=>'2026-10-02T10:28:39+00:00','po-revision-date'=>'2026-10-02T10:28:39+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Media Offload'=>'Zinn® Media Offload','https://zinndigital.com/wordpress-plugins/zinn-offload'=>'https://zinndigital.com/wordpress-plugins/zinn-offload','Moves this site\'s media library to Zinn® object storage and serves it from a CDN. Configured from your Zinn® dashboard — no access key is ever typed into WordPress.'=>'ఈ సైట్ యొక్క మీడియా లైబ్రరీని Zinn® ఆబ్జెక్ట్ స్టోరేజ్‌కి తరలిస్తుంది మరియు దానిని CDN నుండి అందిస్తుంది. మీ Zinn® డ్యాష్‌బోర్డ్ నుండి కాన్ఫిగర్ చేయబడింది — WordPress లో ఎప్పుడూ ఎలాంటి యాక్సెస్ కీ టైప్ చేయబడదు.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Stored. Type a new value to replace it.'=>'భద్రపరచబడింది. దానిని భర్తీ చేయడానికి కొత్త విలువను నమోదు చేయండి.','Filter this list…'=>'ఈ జాబితాను ఫిల్టర్ చేయండి…','Filter this list'=>'ఈ జాబితాను ఫిల్టర్ చేయండి','Nothing matches that filter.'=>'ఆ ఫిల్టర్‌తో ఏదీ సరిపోలడం లేదు.','Add a row'=>'వరుసను జోడించండి','Remove this row'=>'ఈ అడ్డువరుసను తీసివేయండి','Remove'=>'తీసివేయి','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® — స్థూలదృష్టి','Overview'=>'అవలోకనం','Copied'=>'కాపీ చేయబడింది','Every Zinn® plugin on this site, and whether it is working.'=>'ఈ సైట్‌లోని ప్రతి Zinn® ప్లగిన్, మరియు అది పనిచేస్తుందో లేదో.','No connection is needed for this plugin.'=>'ఈ ప్లగిన్ కోసం ఎలాంటి కనెక్షన్ అవసరం లేదు.','Open settings'=>'సెట్టింగ్‌లను తెరవండి','You do not have permission to change these settings.'=>'ఈ సెట్టింగ్‌లను మార్చడానికి మీకు అనుమతి లేదు.','Settings sections'=>'సెట్టింగ్‌ల విభాగాలు','Support'=>'మద్దతు','Save changes'=>'మార్పులను భద్రపరచండి','Tools'=>'సాధనాలు','Export settings'=>'సెట్టింగులను ఎగుమతి చేయ